 switch (true) do {
 	case (_playerDamage >= 0.9): { hint "very damaged"; };
 	case (_playerDamage >= 0.5): { hint "quite damaged"; };
 	case (_playerDamage > 0)   : { hint "slightly damaged"; };
 	default { hint "pristine"; };
